INSERT INTO public.restaurants(id,status,origin_name,naver_name,approved_name,lat,lng,geocoding_success,jibun_address,categories,tzuyang_review,trace_id,youtube_link,evaluation_results,source_type,created_by,updated_by_admin_id,phone) SELECT id,status,origin_name,naver_name,approved_name,lat,lng,geocoding_success,jibun_address,categories,tzuyang_review,trace_id,youtube_link,evaluation_results,source_type,created_by,updated_by_admin_id,phone FROM jsonb_populate_record(NULL::public.restaurants,'{"id": "efe80f2a-965f-4418-a4f7-3f1a78b0b60c", "status": "pending", "origin_name": "fixture branch", "naver_name": "fixture branch", "approved_name": "fixture branch", "lat": 37.5, "lng": 127, "geocoding_success": true, "jibun_address": "synthetic business address", "categories": ["\ud55c\uc2dd", null], "tzuyang_review": "fixture review", "trace_id": "e38f87e71cfe4390b4687c9bec03a11e", "youtube_link": "https://www.youtube.com/watch?v=ABCDEFGHIJK", "evaluation_results": {"visit_authenticity": {"eval_value": 1, "eval_basis": "fixture evidence"}, "rb_inference_score": {"eval_value": 1, "eval_basis": "fixture evidence"}, "review_faithfulness_score": {"eval_value": 1, "eval_basis": "fixture evidence"}, "rb_grounding_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "category_validity_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "category_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "location_match_TF": {"origin_name": "fixture branch", "eval_value": true, "match_status": "matched", "evidence_families": ["source_geo", "provider_candidate"]}}, "source_type": "crawler", "created_by": null, "updated_by_admin_id": null, "phone": "02-777-0000"}'::jsonb);INSERT INTO pipeline_control.restaurant_review_policy(singleton,version,enabled,operator_id,batch_size,daily_limit) VALUES(true,7,true,'00000000-0000-0000-0000-000000000065',1,1);SET LOCAL ROLE service_role;SELECT set_config('request.jwt.claim.role','',true);SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);DO $test$ DECLARE a jsonb;b jsonb;BEGIN a:=public.restaurant_review_automation_tick(gen_random_uuid());IF (a->>'held')::int<>1 OR (a->>'recheck')::int<>0 OR (SELECT status FROM public.restaurants WHERE id='efe80f2a-965f-4418-a4f7-3f1a78b0b60c')<>'hold' THEN RAISE EXCEPTION 'REVIEW_FIX_CATEGORY_TICK';END IF;b:=public.restaurant_review_automation_tick(gen_random_uuid());IF (b->>'scanned')::int<>0 OR EXISTS(SELECT 1 FROM pipeline_control.restaurant_review_items WHERE state IN('queued','running')) THEN RAISE EXCEPTION 'REVIEW_FIX_CATEGORY_TICK_REPEAT';END IF;END $test$;ROLLBACK;